def banner(lang):
 _,head,body=COPY[lang]
 return f'[h2][url={LINK}]{head}[/url][/h2]\n{body}\n\n'
def preserve_navigation(item_id, language, title, description, current):
 if item_id not in TITLES or language not in COPY or (title is None and description is None):
  return title, description
 title=TITLES[item_id][language]
 description=current['description'] if description is None else description
 if item_id != 3828956017 and not description.startswith(banner(language)):
  description=banner(language)+description
 return title,description
